// Module 2 — Office Automation (Word, Excel, PowerPoint)
// Rewritten for 17-year-old first-time ICT students at Amity Tashkent.
// Plain English, short sentences, Uzbek/Tashkent scenarios, no deep jargon.
// Bloom's: Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze ·
// Q9 Evaluate · Q10 Create. Correct answer is NEVER the longest option.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Editing vs Word Processing ───
  1: [
    { q: "What is a text editor, in simple words?", opts: ["A program that types plain letters only, with no bold, colour, or pictures at all", "A program that can print any file and automatically make the text larger and clearer", "A program that plays music and short videos in the background while you type", "A program that turns your handwriting into typed text with a built-in smart camera"], ans: 0, why: "A text editor like Notepad handles plain characters only. No bold, no colours, no pictures. Printing nicely, playing music, or reading handwriting are things other programs do \u2014 not a text editor.", bloom: "remember" },
    { q: "What is a word processor, in simple words?", opts: ["It is a calculator program that does maths on numbers you type into rows and columns quickly", "A program that types letters AND adds bold, colour, pictures, tables, and spell-check", "It is a presentation program used to show slides on a big screen to an audience of classmates", "It is a tiny program that only works on phones and cannot open on any normal laptop at home"], ans: 1, why: "A word processor (like MS Word or Google Docs) types letters PLUS formats them \u2014 bold, colour, pictures, tables, spell-check, page layout. A calculator is Excel, slides is PowerPoint, and word processors work great on laptops.", bloom: "remember" },
    { q: "Why do we say \u201cword processing INCLUDES editing\u201d?", opts: ["Because editing and word processing are two different names for exactly the same thing today", "Because word processing is the simple part and editing is the much more advanced extra part", "Editing (typing, deleting) is the basic part; word processing adds formatting on top of it", "Because every laptop in the world ships with both editing and word processing pre-installed now"], ans: 2, why: "Editing = typing and deleting. Word processing = editing PLUS bold, colour, pictures, tables. So every word processor also does editing, but Notepad (a pure text editor) cannot do word processing.", bloom: "understand" },
    { q: "Why is a .txt file (from Notepad) smaller than a .docx file (from Word) that has the same words?", opts: ["Because .docx files are always broken and add lots of useless empty data to every single document", "Because .txt stores only letters; .docx also stores formatting, images, and layout info", "Because MS Word compresses every file you make to be exactly twice the size of the original text", "Because Notepad removes every second letter from your text to save space on your hard drive"], ans: 1, why: ".txt saves plain characters only. .docx saves those characters PLUS the styling \u2014 fonts, sizes, colours, images, paragraph layout. More info stored = bigger file. Notepad does not delete letters.", bloom: "understand" },
    { q: "Your teacher asks for a \u201cword-processed\u201d school report with headings and images. Which app should you use?", opts: ["Notepad, because Notepad is already installed on every single computer in the whole school building", "Calculator, because a school report always needs many maths calculations in every single paragraph", "MS Word or Google Docs, because both can do headings, images, and page layout for a report", "Paint, because you can draw the title in Paint and then write the rest of the report by hand"], ans: 2, why: "Headings and images are formatting \u2014 a word-processor job. MS Word or Google Docs do this easily. Notepad has no formatting. Calculator is for maths. Paint is for drawings.", bloom: "apply" },
    { q: "You want to save one friend\u2019s phone number really fast. Which app is the quickest choice?", opts: ["Open Notepad, type the number, save as .txt \u2014 it opens instantly and the file is tiny", "Open MS Word, wait for the ribbon to load, type the number, and save as a full .docx file", "Open PowerPoint, create a new slide, type the number, and save as a big .pptx file", "Open Excel, click a cell, type the number, format it as a phone number, and save the workbook"], ans: 0, why: "For ONE tiny piece of text, Notepad opens in a blink and the file is small. Word, PowerPoint, and Excel are too big for this simple job. Use the simplest tool when the task is simple.", bloom: "apply" },
    { q: "Your cousin sends you his CV as a .txt file. It \u201clooks flat\u201d \u2014 no bold name, no headings. Why?", opts: ["The file probably got broken somewhere on the way and needs to be downloaded again from a different device soon", "Your cousin\u2019s laptop is probably broken and it stripped all the colours and the bold from the file before sending it off", "Your own laptop deleted all the formatting when you opened it because of a missing font on your own system", "A .txt file only stores plain letters, so bold, colour, and headings can\u2019t be saved in it"], ans: 3, why: ".txt files store plain characters only \u2014 no formatting can live inside them. Even if your cousin made it bold in Notepad (he couldn\u2019t!), .txt simply has no room for styling. The file is not broken.", bloom: "apply" },
    { q: "A student writes a 5-page essay in Notepad and submits a .txt file. The teacher says \u201cno formatting.\u201d What did the student misunderstand?", opts: ["The student thought Notepad would always add formatting automatically on submit to the school server", "The student didn\u2019t know that editing and word processing are different \u2014 Notepad cannot format", "The student\u2019s laptop probably uses a broken version of Notepad that simply strips all the formatting", "The student forgot to turn on dark mode inside Notepad, which would have added proper headings"], ans: 1, why: "The student confused editing (what Notepad does) with word processing (what Word does). Notepad CAN\u2019T format \u2014 it was never designed to. Dark mode and auto-formatting don\u2019t exist in Notepad.", bloom: "analyze" },
    { q: "Your friend says: \u201cMS Word is always better than Notepad \u2014 Notepad is useless!\u201d Is this a good view?", opts: ["Yes \u2014 Notepad is from the 1990s and every single modern student has no good reason to ever use it for any school task now", "Yes \u2014 MS Word can do everything that Notepad can do and a whole lot more on top of that, so students should just use Word always", "Not quite \u2014 Notepad wins for quick notes, small files, and code; Word is for formatted work", "No \u2014 Notepad is always faster and better than MS Word for every single school task a student might ever face in any class"], ans: 2, why: "Both tools have their place. Word is better when you need formatting (essays, CVs). Notepad is better when you need speed, small files, or plain text (quick notes, code, phone numbers). \u201cAlways better\u201d is too strong.", bloom: "evaluate" },
    { q: "Design a simple rule for your class: when should you use Notepad vs MS Word?", opts: ["Always use MS Word for everything at school, even for a one-line note, because it\u2019s the newest app", "Never use either app \u2014 always write every single assignment and quick note with a pen on paper", "Always use Notepad because MS Word is too slow and fancy for school-level writing tasks in any form", "Notepad for quick plain notes (shopping list, phone number); MS Word for essays and letters"], ans: 3, why: "Match the tool to the job. Quick plain text (notes, numbers, code) \u2192 Notepad, fast and small. Essays, letters, CVs, reports \u2192 Word, for headings, bold, images. \u201cAlways one app\u201d fails either on size or on formatting.", bloom: "create" },
  ],

  // ─── Topic 2: MS Word — Text Editing & Formatting ───
  2: [
    { q: "What is the \u201cRibbon\u201d in MS Word?", opts: ["It is the flashing line that shows where the next letter you type will appear in your document", "The strip of tabs and buttons at the top of the window (Home, Insert, Layout, and more)", "It is the scroll bar on the right side that helps you move up and down inside a long document", "It is the narrow status bar at the very bottom of the window that shows the total word count"], ans: 1, why: "The Ribbon is the wide toolbar at the top of Word, divided into tabs like Home, Insert, Layout. The flashing line is the cursor, the bar on the right is the scroll bar, and the status bar is at the bottom.", bloom: "remember" },
    { q: "Which keyboard shortcut makes the selected text bold in MS Word?", opts: ["Ctrl+B \u2014 the letter B is the hint that it stands for Bold on Windows keyboards", "Ctrl+I \u2014 which actually turns the selected text into italic (slanted), not bold at all", "Ctrl+U \u2014 which draws a line under the selected text, nothing to do with bold at all", "Ctrl+P \u2014 which opens the Print dialog box and does not change any text formatting at all"], ans: 0, why: "B = Bold. I = Italic. U = Underline. P = Print. The letter is always the hint on these shortcuts. They also work in Google Docs, Gmail, and most Windows apps.", bloom: "remember" },
    { q: "Why must you SELECT text BEFORE pressing Ctrl+B to make it bold?", opts: ["Word is old software and this rule is just a leftover from older versions that Microsoft never removed", "Word needs to know WHICH text to bold \u2014 without a selection, it has no target to change", "Selection speeds Word up because the program can skip processing text that is not selected right now", "Selection is actually optional these days, and modern MS Word will just bold the whole page for you"], ans: 1, why: "A formatting button changes whatever is selected. No selection = Word doesn\u2019t know what to change, so nothing happens. This applies to bold, italic, colour, font, size \u2014 anything you click on the Ribbon.", bloom: "understand" },
    { q: "Why does Word\u2019s Ribbon split into tabs (Home, Insert, Layout) instead of one giant toolbar?", opts: ["Word has too many buttons to show on one screen, so grouping them helps people find things", "Because the tabs are older buttons that Microsoft kept only for people who use the very old Windows versions at home", "Because the Ribbon\u2019s tabs are actually a paid-only feature that only appears after you buy the premium version of MS Word", "Because Word secretly hides some of its features behind the tabs in order to sell the more expensive version of Microsoft Office"], ans: 0, why: "Word has hundreds of tools. Grouping them into tabs by purpose (Home = format text, Insert = add pictures) makes them findable. One long toolbar would be impossible to scan. The other options are untrue.", bloom: "understand" },
    { q: "You want a formal paragraph with BOTH the left AND right edges perfectly straight, like a newspaper. Which alignment fits?", opts: ["Left (Ctrl+L) \u2014 the default alignment you see in almost every new MS Word document that you open", "Centre (Ctrl+E) \u2014 which puts each line in the middle of the page, like a title or a birthday invitation", "Right (Ctrl+R) \u2014 which pushes every line all the way to the right edge of the page, used for dates", "Justify (Ctrl+J) \u2014 which stretches the spaces so both edges are straight, newspaper-style"], ans: 3, why: "Justify = both edges straight (newspaper look). Ctrl+J is the shortcut. Left = only left straight. Centre = middle. Right = right straight. Each alignment fits a different purpose.", bloom: "apply" },
    { q: "You typed an essay title but forgot to make it look like a title. What is the quickest fix?", opts: ["Retype the whole title three times, once in bold, once larger, and once centred, then pick the best one", "Ask a friend to open your file on their laptop and format the title for you while you wait nearby", "Select the title \u2192 press Ctrl+B for bold \u2192 press Ctrl+E to centre \u2192 raise the font size to 18", "Delete the whole essay and start a new document from scratch, typing the title in bold from the very beginning"], ans: 2, why: "Three quick clicks on the selected title: bold (Ctrl+B), centre (Ctrl+E), bigger font. Retyping, asking friends, or starting over wastes time. Word is built for exactly this \u2014 small edits to existing text.", bloom: "apply" },
    { q: "You formatted one paragraph perfectly and want the SAME look on five other paragraphs. What is the fastest way?", opts: ["Retype the five paragraphs one by one, remembering to apply every formatting choice manually each time", "Use Format Painter: click the good paragraph \u2192 click the little paintbrush \u2192 drag over the other five", "Delete every other paragraph and keep only the one that you already formatted perfectly the first time", "Copy the perfect paragraph and paste it five times on top of each of the other paragraphs one by one"], ans: 1, why: "Format Painter (the paintbrush icon) copies ONLY the formatting, not the text. Click the source, click the brush, drag over the target \u2014 same look, different words. Way faster than redoing everything by hand.", bloom: "apply" },
    { q: "A student writes a CV with no bold, no size changes, and the same font for everything \u2014 including name, contact info, and job list. Why is this a problem?", opts: ["The CV file will definitely not open on the company\u2019s laptop because Word needs formatting to display correctly", "Word will not let the student save a CV without at least one bold word, due to a built-in rule", "Without formatting, the reader can\u2019t quickly scan for name, headings, or sections \u2014 it all looks the same", "The student\u2019s internet is too slow to save formatting, so the CV will arrive at the employer without any style"], ans: 2, why: "Formatting guides the reader\u2019s eye. A CV with NO formatting looks like a blob of text \u2014 the employer can\u2019t find the name, the education, or the jobs quickly. That often means the CV is skipped. Formatting is communication.", bloom: "analyze" },
    { q: "Your classmate says: \u201cKeyboard shortcuts are a waste of time \u2014 the Ribbon buttons are easier.\u201d Evaluate.", opts: ["Fully correct \u2014 shortcuts are only for professional typists, not school students learning MS Word", "Fully wrong \u2014 the Ribbon is totally useless and every student should memorise 200 shortcuts on day one", "Fully correct \u2014 nobody in any office job today ever actually uses any keyboard shortcut to format text", "Not quite \u2014 buttons are fine when learning, but a few key shortcuts (Ctrl+S, Ctrl+Z) save real time"], ans: 3, why: "Ribbon buttons are great for features you use rarely. Shortcuts are great for things you do every few seconds (save, undo, bold). Most people learn a small set (5\u201310) and use the Ribbon for the rest. A balanced view wins.", bloom: "evaluate" },
    { q: "Design a short formatting plan for a one-page formal letter to your school director.", opts: ["Make every single word bold, in five different colours, and use every font that MS Word has installed on the laptop", "Don\u2019t format anything at all \u2014 just type plain text with no spaces, no headings, and no title at the very top of the page", "Title centred+bold \u00b7 date on the right \u00b7 left-aligned body size 12 \u00b7 bold name at bottom", "Use the biggest possible font size for the whole letter so that the director can easily read every word from across the room"], ans: 2, why: "Each piece has a purpose: centred bold title draws the eye; right-aligned date is a formal convention; left-aligned body is easy to read; bold signature stands out. Chaos or no-formatting fails. Giant fonts for everything look childish.", bloom: "create" },
  ],

  // ─── Topic 3: MS Word — Images & Tables ───
  3: [
    { q: "Which tab on the MS Word Ribbon do you use to add a picture or a table to your document?", opts: ["The Home tab, which mostly holds buttons for bold, italic, font size, and paragraph alignment only", "The View tab, which changes how the document looks on your screen (zoom, ruler, and similar)", "The Insert tab, which is where buttons for pictures, tables, shapes, and charts all live together", "The File tab, which opens the menu for saving your document, printing, and starting a new file"], ans: 2, why: "Insert = \u201cadd stuff.\u201d Pictures, tables, shapes, charts, and headers all live there. Home is for formatting text. View is for screen settings. File is for save/print/open.", bloom: "remember" },
    { q: "Why should you drag from the CORNER handle (not the side) when resizing a picture?", opts: ["Corner dragging keeps the picture\u2019s shape \u2014 side dragging squashes it and makes people look weird", "Corner handles are faster to click than side handles because they are much bigger on the screen", "Side handles only work on the newest versions of MS Word, while corner handles work everywhere", "There is really no difference \u2014 corner and side both do the same thing in any modern version of Word"], ans: 0, why: "Corner = keeps the width-to-height ratio \u2014 the picture just gets bigger or smaller. Side = stretches one way only, so faces look squashed or stretched. The difference is VERY visible on photos of people.", bloom: "remember" },
    { q: "Why does MS Word have different \u201ctext wrapping\u201d options like Square and In Line with Text?", opts: ["Because In Line is only for old Word versions and no student should ever pick it on a modern laptop", "Because they control how text behaves around your picture \u2014 each option fits a different layout", "Because Microsoft sells the Square option as a paid extra and In Line is the only free choice today", "Because they change the picture\u2019s colours \u2014 Square is a warmer look and In Line is a colder look"], ans: 1, why: "Wrapping sets how text flows around the picture. Square = paragraph wraps around the box (for photos in reports). In Line = picture behaves like a letter, for a small icon inside a line of text. Different layouts, different choices.", bloom: "understand" },
    { q: "Why does Word show a grid when you click Insert \u2192 Table and let you hover over it?", opts: ["So you can quickly pick how many rows and columns the table will have, without opening any dialog box", "Because the grid is just decoration and does nothing \u2014 you always have to type the row and column count by hand", "Because older Word versions did not have tables, and the grid is a warning shown to modern users now", "Because every Word table must have exactly 6 rows and 6 columns \u2014 the grid shows that fixed size"], ans: 0, why: "The grid lets you slide the mouse to pick size visually \u2014 3 across and 4 down, for example \u2014 and click. Much faster than opening a dialog and typing numbers. It is not decoration or fixed-size.", bloom: "understand" },
    { q: "You are writing a school history project and want a photo of the Registan with the paragraph flowing nicely around it. Which wrapping option?", opts: ["In Line with Text, which will put the photo onto one line and push the paragraph into a weird shape", "Behind Text, which will put the photo UNDER the paragraph and make the words sit on top of the image", "There is no setting for this in MS Word \u2014 you have to just type the paragraph below the photo each time", "Square, which wraps the paragraph neatly around the photo\u2019s box \u2014 exactly the look of a report"], ans: 3, why: "Square is the standard choice for \u201cphoto in a paragraph.\u201d Text flows around the picture\u2019s box. In Line breaks the paragraph. Behind Text hides the paragraph under the photo \u2014 useful for watermarks only.", bloom: "apply" },
    { q: "You need a 3-column, 5-row timetable for your school week. What is the fastest way in MS Word?", opts: ["Draw each line by hand using the pen tool under Insert, which takes a long time to line up correctly", "Type the days and subjects as plain text with many, many spaces between them to line up the columns manually", "Go to Insert \u2192 Table, hover the grid to pick 3 columns by 5 rows, and click. Then type in each box", "Open a new PowerPoint file, make a 3x5 table there, then copy it over as a picture into MS Word carefully"], ans: 2, why: "Insert \u2192 Table \u2192 hover grid \u2192 click = two seconds. Spaces never line up between columns. Drawing by hand is slow and bumpy. PowerPoint detour is unnecessary \u2014 Word has tables built in.", bloom: "apply" },
    { q: "Your birthday invitation has one photo of the cake. You want the photo to fill the whole page with words on top. Which wrapping?", opts: ["Square, because the text will wrap around the photo and still leave a nice visible border around it", "In Line with Text, because the photo will act like a big letter inside the first line of the paragraph", "Tight, because this always turns the photo into a background without covering any of the writing at all", "Behind Text, because the photo will sit BEHIND the words and the invitation text will appear on top"], ans: 3, why: "Behind Text is the classic \u201cbackground image\u201d choice \u2014 photo fills the page and text sits over it. Square keeps photo and text separate. In Line makes the photo behave like a character, not a background. Tight wraps tightly around shapes, not backgrounds.", bloom: "apply" },
    { q: "A student\u2019s school report has 10 photos packed onto one page with only one line of text between each. What problem does this create for the reader?", opts: ["The file will automatically become corrupted and will not open on the teacher\u2019s laptop when it is submitted", "The page looks crowded and the reader can\u2019t tell which picture belongs to which idea \u2014 it loses meaning", "MS Word will refuse to print the page because there is a limit of 3 images per A4 page in the Home tab", "Nothing is wrong \u2014 more images always means a higher mark from the teacher in every single school subject"], ans: 1, why: "Images help when they support an idea. 10 photos on one page is visual noise \u2014 the reader can\u2019t connect text to image, and the page looks messy. Word does not limit images per page. Files don\u2019t corrupt from too many photos.", bloom: "analyze" },
    { q: "Your friend says: \u201cAlways use tables in Word \u2014 they are the best way to arrange everything on a page.\u201d Evaluate.", opts: ["Fully right \u2014 every page of every document should be built using a hidden table for the neatest possible arrangement", "Fully wrong \u2014 tables in MS Word are completely broken and no professional team anywhere uses tables in any report today", "Not quite \u2014 tables are great for data rows and columns, but awkward for page layout", "Fully right \u2014 tables are the only way to make anything look neat on a page in every single version of MS Word ever released"], ans: 2, why: "Tables are perfect when content IS rows and columns (timetable, shopping list, marks). Using hidden tables for general layout makes files hard to edit and confuses screen readers. Match the tool to the content.", bloom: "evaluate" },
    { q: "Design the layout for a one-page class project report on \u201cMy Favourite Sport\u201d using pictures and a table.", opts: ["Fill the whole page with only pictures and no text at all, so the reader can guess what the sport is by looking at them", "Bold title \u00b7 one photo (Square wrap) next to a paragraph \u00b7 small 3-col stats table", "Paste about 20 separate small pictures across the page with no text, no heading, and no table of any information at all", "Use a single giant table that covers the whole page and type every word and paste every picture inside one very big cell"], ans: 1, why: "A good layout mixes tools by purpose: title at top for identity, one photo + paragraph (Square wrap) for the main story, small table for facts (wins, goals, matches). Picture-only has no info; 20 random pictures is chaos; one giant cell misuses tables.", bloom: "create" },
  ],

  // ─── Topic 4: MS Excel — Creating Worksheets ───
  4: [
    { q: "What does the name \u201ccell B3\u201d mean in MS Excel?", opts: ["The third cell down from the top inside column B \u2014 it is the same as row B and column 3 in old Excel", "The cell where column B and row 3 meet \u2014 Excel writes the column letter first, then the row number", "The third sheet in your workbook that happens to be renamed with the letter B for some personal reason", "A cell that only accepts the letter B or the number 3 inside and rejects every other kind of input given"], ans: 1, why: "Excel cell addresses are always [column letter][row number]: B = second column, 3 = third row. B3 is where they meet. Excel does not accept row-first style, and cells accept any type of data.", bloom: "remember" },
    { q: "What is the difference between a Worksheet and a Workbook in Excel?", opts: ["A Worksheet is the whole Excel file; a Workbook is just one single sheet tab inside the file", "They are two different names for the exact same thing and can be used in any way you want in class", "A Workbook is the whole file; a Worksheet is one tab (one page of cells) inside the file", "A Worksheet can hold only numbers and a Workbook can hold only text \u2014 never both at the same time"], ans: 2, why: "Workbook = the whole .xlsx file. Worksheet = one tab (page of cells) inside it. One workbook can contain many worksheets. The other options swap the terms or invent fake rules.", bloom: "remember" },
    { q: "Why do column letters jump from Z to AA (not back to A) in Excel?", opts: ["Because AA is always the very first column \u2014 Z is actually the 27th column, not the 26th one", "Because Excel skips some letters on purpose \u2014 A comes back after AA finishes, to reuse letter names", "Single letters are reserved for secret hidden columns that only Excel developers can see and edit", "The alphabet only has 26 letters \u2014 after Z, Excel doubles up to AA, AB, AC to make more columns"], ans: 3, why: "After A\u2013Z (26 columns), Excel continues AA, AB, \u2026 AZ, then BA, BB, \u2026 ZZ. This gives 676 two-letter columns. There are no \u201chidden\u201d letters or swapped positions.", bloom: "understand" },
    { q: "Why is a whole .xlsx file called a \u201cWorkbook\u201d and one tab a \u201cWorksheet\u201d?", opts: ["Names come from paper: one book holds many pages, so one file holds many sheets", "Because Microsoft accidentally got the names completely wrong back in the 1990s and never bothered to rename them in any update", "Because a Worksheet is actually the full file and a Workbook is just one single tab \u2014 the English words simply confuse most students", "Because every Excel Workbook has exactly 12 Worksheets inside it \u2014 one for each month of the calendar year, without exception"], ans: 0, why: "The names come from paper: a physical book has many pages. Excel follows the same idea \u2014 one workbook (file) holds many worksheets (pages/tabs). There is no fixed count of 12, and the naming is not a mistake.", bloom: "understand" },
    { q: "You want to list 5 shopping items and their prices in Excel. Where should the headings \u201cItem\u201d and \u201cPrice\u201d go?", opts: ["A1 and B1 \u2014 one heading per column, with the actual items starting in row 2 below the headings", "A1 and A2 \u2014 stacking both headings in the same column one above the other to save horizontal space", "C5 and C6 \u2014 placing the headings in the middle of the sheet so they look centred on the screen", "Nowhere \u2014 Excel does not need any headings because it figures out each column type all by itself"], ans: 0, why: "Headings go in row 1, one per column: A1 = Item, B1 = Price. Data starts in row 2. Same-column headings or middle placement makes it hard to sort and filter later. Excel does need headings for clarity.", bloom: "apply" },
    { q: "You typed \u201c5000\u201d in a cell but it sits on the LEFT and won\u2019t add in SUM. Why and how do you fix it?", opts: ["Excel is broken \u2014 restart the laptop and the problem will go away on its own next time you try", "The number 5000 is just too big for Excel to understand at once \u2014 split it into 5 and 000 in two cells", "Your keyboard typed a strange invisible letter \u2014 delete the cell content and type it again in uppercase", "The cell is formatted as Text, so Excel thinks \u201c5000\u201d is a word \u2014 change Format to Number"], ans: 3, why: "Numbers align RIGHT in Excel. If a number aligns LEFT and won\u2019t SUM, it is stored as text. Fix: change Format Cells to Number, or retype in a fresh cell. Numbers are not too big; this is a formatting issue.", bloom: "apply" },
    { q: "Your family wants to track pocket money in Excel for 3 people (you, your brother, your sister). Which structure is simplest?", opts: ["One sheet, columns A B C D = Date, You, Brother, Sister \u2014 one row per day, one amount per person", "One separate Excel file per person, three files to open every day when you want to enter any data", "Use row 1 for your data, row 2 for brother\u2019s, row 3 for sister\u2019s \u2014 only three rows for the whole month", "Write everything in column A as one long sentence per day like \u201cAli 5000, Dilnoza 3000\u201d and skip cells"], ans: 0, why: "One sheet, one column per person, one row per day \u2014 clean and easy to SUM at the bottom. Three files is slow to update. Three rows has no room for many days. Long sentences in one cell break every Excel feature (sorting, filtering, totals).", bloom: "apply" },
    { q: "Your cousin saves his class marks in 25 separate Excel files (one per student). Why is this structure a problem?", opts: ["Excel files with few data cells become corrupted after one week and cannot be opened by any version of Excel", "Finding the class average is hard \u2014 you\u2019d have to open 25 files and copy numbers by hand to get any total", "Opening 25 Excel files will permanently crash any laptop because Excel only allows one file at a time", "Having 25 files is always the best choice \u2014 there is no downside and it helps the teacher mark faster"], ans: 1, why: "One file with 25 rows (one per student) is much easier: SUM, AVERAGE, SORT, FILTER all work in one click. 25 separate files is painful to compare or total. Files don\u2019t corrupt from small data; Excel opens many files at once.", bloom: "analyze" },
    { q: "A friend says: \u201cExcel is only useful if you know maths \u2014 I hate maths, so I\u2019ll never use it.\u201d Evaluate.", opts: ["Fully correct \u2014 only serious maths people ever open MS Excel, and it is useless for anyone else in life", "Not quite \u2014 Excel also helps with simple lists, dates, timetables, and tracking daily items, not only maths", "Fully wrong \u2014 Excel is purely a pretty-table program and has nothing to do with maths at any level at all", "Fully correct \u2014 everyone in every office job in every country today uses Python instead of Excel for every task"], ans: 1, why: "Excel is great at lists, tracking, and sorting, NOT only maths. A birthday list, a phone directory, a class register, a school timetable \u2014 all great Excel use cases. Maths is one feature, not the whole tool.", bloom: "evaluate" },
    { q: "Design an Excel workbook for a small school canteen that sells 5 items, tracking sales for the whole week.", opts: ["One giant file with every sale written as one long sentence inside cell A1, no columns or rows needed", "One sheet per single sale, with a new file created every time any customer buys a samsa or a drink", "Columns: Day \u00b7 Item \u00b7 Price \u00b7 Quantity \u00b7 Total \u2014 one row per sale, and a SUM at the bottom", "Paste a photo of the canteen menu into cell A1 as the only thing and type nothing else anywhere"], ans: 2, why: "Good Excel structure has named columns, one row per record, and formulas at the bottom. Sentences in A1, one-sheet-per-sale, and a photo-only design all throw away Excel\u2019s superpowers (sorting, filtering, totals).", bloom: "create" },
  ],

  // ─── Topic 5: MS Excel — Formulas & Functions ───
  5: [
    { q: "What symbol MUST every Excel formula start with, and why?", opts: ["A hashtag (#), which Excel uses to label formulas as important inside every cell you are filling", "An equals sign (=), which tells Excel \u201cwhat comes next is a formula, please calculate it\u201d", "A pound (\u00a3), which Excel uses to mark currency but is also required for any type of formula today", "A small letter f, which stands for \u201cformula\u201d and starts every calculation in every modern version of Excel"], ans: 1, why: "= tells Excel \u201ccalculate this.\u201d Without it, Excel just shows your typing as plain text. A1+B1 is text. =A1+B1 is the sum. No other symbol triggers a formula. # and \u00a3 have other meanings; f is not a prefix.", bloom: "remember" },
    { q: "What does the formula =SUM(A1:A5) do?", opts: ["It adds every value from cells A1, A2, A3, A4, and A5 together and returns the final total as one number", "It counts how many cells in the range A1 to A5 contain a number, and returns that count as the answer", "It multiplies every value from A1 to A5 and gives you the total product of all those numbers as output", "It finds the biggest number inside the range A1 to A5 and returns only that one number, ignoring the rest"], ans: 0, why: "SUM adds. The colon means \u201cfrom\u2026 to\u2026\u201d so A1:A5 is every cell from A1 down to A5. Count is COUNT, multiply is PRODUCT, biggest is MAX \u2014 different functions.", bloom: "remember" },
    { q: "Why does =A1+B1 update automatically when you change the number in A1?", opts: ["The formula remembers the addresses of cells \u2014 when any of those cells change, Excel redoes the sum", "Excel automatically refreshes every single formula only when the user manually clicks a refresh button", "The formula becomes a plain number once you press Enter, and that number never updates on its own", "Formulas do not actually update when you change a cell \u2014 you always have to retype them every time"], ans: 0, why: "A formula stores the ADDRESS (A1, B1), not the values. Whenever those cells change, Excel redoes the sum instantly. This is the whole superpower of Excel. The other options describe static numbers, not formulas.", bloom: "understand" },
    { q: "Why is =AVERAGE(B1:B5) different from just adding B1..B5 and dividing by 5?", opts: ["They always give exactly the same answer in every case, so there is really no difference at all", "If some cells in the range are empty, AVERAGE divides by the COUNT of numbers, not by a fixed 5", "Only AVERAGE works with ranges \u2014 dividing by 5 gives a #VALUE error in every version of MS Excel", "AVERAGE always rounds to a whole number, but division by 5 gives the exact result with decimal places"], ans: 1, why: "If 2 of the 5 cells are empty, AVERAGE divides the sum by 3 (only real numbers). Manual /5 divides by 5 \u2014 a different answer. AVERAGE handles blanks the smart way. The results differ whenever data is incomplete.", bloom: "understand" },
    { q: "Your mum buys 4 non (bread) at 3000 UZS each. Which formula gives the total cost in one cell?", opts: ["=3000+4, which simply adds the two numbers together and gives you 3004 UZS, which is not the total cost at all", "=SUM(3000), which only returns 3000 UZS because the SUM function needs a range or a list, not just one single number", "=3000*4, which multiplies price by quantity, giving 12000 UZS", "=3000/4, which divides the price by the quantity and returns 750 UZS \u2014 the cost if split among four people, not the total"], ans: 2, why: "Total = price \u00d7 quantity. 3000 * 4 = 12,000 UZS. Using + gives a nonsense sum. SUM of one number returns that number. / is division \u2014 a different question.", bloom: "apply" },
    { q: "You have shop prices in column B (B2 to B20). Which formula finds the MOST EXPENSIVE item\u2019s price?", opts: ["=SUM(B2:B20), which simply adds all the prices together and gives the total spending for the whole shop", "=AVERAGE(B2:B20), which calculates the middle price across the full range of items in that list", "=MIN(B2:B20), which finds the cheapest item \u2014 exactly the opposite answer to what the question asks", "=MAX(B2:B20), which returns the biggest number in the range \u2014 i.e. the most expensive item\u2019s price"], ans: 3, why: "MAX = the biggest. MIN = the smallest. SUM = total. AVERAGE = middle. For \u201cmost expensive,\u201d use MAX. The opposite would be MIN for cheapest.", bloom: "apply" },
    { q: "Your class has 30 test scores in B2:B31. Which formula gives the class average?", opts: ["=SUM(B2:B31)/30, which always works correctly even if some students were absent and their cell is empty", "=MAX(B2:B31), which actually returns the highest score in the class, not the average of all students", "=AVERAGE(B2:B31), which adds the scores, then divides by how many numbers exist \u2014 even with blanks", "=COUNT(B2:B31), which counts how many students took the test but does not compute the average mark"], ans: 2, why: "AVERAGE is the safe choice \u2014 it handles empty cells (absent students) by dividing by the real count, not a fixed 30. /30 fails when some are absent. MAX gives top score. COUNT gives headcount. Use the right function.", bloom: "apply" },
    { q: "Your Excel cell shows \u201c#####\u201d instead of a number. What is happening and how do you fix it?", opts: ["The file is corrupted and must be restored from an older version on your USB stick or cloud drive", "The column is too narrow to show the number \u2014 double-click the column border to auto-widen it", "The formula is wrong \u2014 you must delete the formula and retype it carefully using all capital letters", "The cell has too many decimal places \u2014 Excel shows # to warn you to round the number off soon"], ans: 1, why: "##### means \u201cthe number exists but the column is too narrow to display it.\u201d Widen the column (double-click the right edge of the column letter) and the number appears. File is fine, formula is fine.", bloom: "analyze" },
    { q: "Your friend says: \u201cI don\u2019t need formulas \u2014 I can just use a phone calculator and type the answer into Excel.\u201d Evaluate.", opts: ["Fully correct \u2014 formulas are for professionals only, and school students should just use their phone calculator", "Fully wrong \u2014 nobody in the world ever uses a phone calculator after learning about any version of MS Excel", "Fully correct \u2014 Excel formulas are a waste of time because the answer is always the same anyway every time", "Not quite \u2014 typing answers works once, but formulas update when data changes \u2014 no retyping forever"], ans: 3, why: "Typing a calculated answer works \u2014 once. The moment a number changes, you retype the answer. Formulas update automatically forever. For any data that might change (prices, marks, budgets), formulas are worth the small effort to learn.", bloom: "evaluate" },
    { q: "Design a simple weekly pocket money sheet: 7 rows for days, columns for money received and money spent, with totals at the bottom.", opts: ["Type a fixed number 50000 in one cell and ignore daily changes \u2014 it\u2019s close enough for most school weeks", "Type every day\u2019s total by hand at the bottom and retype the total whenever any daily amount changes", "Columns A B C = Day, Received, Spent \u00b7 rows 2\u20138 = the 7 days \u00b7 B9 =SUM(B2:B8) \u00b7 C9 =SUM(C2:C8)", "Make seven completely separate files, one per day, and never attempt to calculate any weekly total"], ans: 2, why: "Headings in row 1, 7 rows of data, =SUM at the bottom for each money column. Change any daily amount \u2192 totals update instantly. Fixed numbers ignore reality; manual retyping wastes time; 7 files is silly.", bloom: "create" },
  ],

  // ─── Topic 6: MS Excel — Data Management ───
  6: [
    { q: "What is the simplest definition of SORTING in Excel?", opts: ["Sorting permanently deletes every row that does not match the chosen condition inside the big data table", "Sorting rearranges the rows into a new order \u2014 A to Z, smallest to biggest, or oldest to newest", "Sorting always adds a brand new column called \u201cSort\u201d to your data sheet every time you press the button", "Sorting hides the rows that don\u2019t match a chosen rule \u2014 it keeps them, but you can\u2019t see them right now"], ans: 1, why: "Sort = reorder rows (A\u2013Z, 1\u20139, oldest\u2013newest). No deletion, no new columns. Hiding rows that don\u2019t match is FILTER, not sort.", bloom: "remember" },
    { q: "What is the simplest definition of FILTERING in Excel?", opts: ["Filtering hides the rows that don\u2019t match your rule \u2014 those rows are still there, just not visible now", "Filtering deletes rows that do not match the rule and removes them permanently from your Excel workbook file", "Filtering changes the alphabetical order of your data based on the rule the user chose in the dialog box", "Filtering copies every row into a second sheet and then leaves the original sheet completely empty"], ans: 0, why: "Filter = hide rows that don\u2019t match, keep ones that do. No deletion. Rearranging order is SORT, not filter. Copying to another sheet is a separate feature.", bloom: "remember" },
    { q: "Why is filtering called \u201cnon-destructive\u201d?", opts: ["Because Excel makes a hidden back-up copy of every row just before you press the filter button each time", "Because filters only work for 24 hours and the filter then automatically turns itself off and restores the rows", "Because Excel sends you a warning pop-up every time a filter is about to remove any row from your data sheet", "Because the rows that don\u2019t match are only hidden from view \u2014 they are still saved in the file, not deleted"], ans: 3, why: "A filter only changes what you see \u2014 the hidden rows remain in the file. Clear the filter and they come back. No backups needed, no timers. This is why you can safely filter a shared file.", bloom: "understand" },
    { q: "Why might sorting ONE column accidentally mess up the rest of your data table?", opts: ["If you select only that one column, Excel may move only its values, leaving the other columns stuck in place", "Because Excel always picks a random column to sort instead of the one you selected, which causes confusion", "Because sorting always scrambles your whole sheet permanently no matter which cells you select first in Excel", "Because Excel sorts only one column at a time and gives an error pop-up if you select the whole data range"], ans: 0, why: "If you sort only one column without the rest, that column\u2019s values move but the other rows stay \u2014 breaking the match (Ali\u2019s score ends up next to Dilnoza\u2019s name). Always select the whole data range or use Data \u2192 Sort.", bloom: "understand" },
    { q: "You have a class of 200 students and want to see ONLY students in Grade 10 who scored above 80. Which approach?", opts: ["Delete every row that doesn\u2019t match either rule one by one, which permanently removes them from your data", "Sort the list from highest to lowest and read the top ten rows by eye \u2014 close enough for most teachers", "Copy all the rows into a new sheet and delete every row that does not match both rules manually by hand", "Apply a Filter on Grade (=10) AND a Filter on Score (>80) together to see only the matching rows safely"], ans: 3, why: "Multiple filters combine with AND. Show only Grade = 10 AND Score > 80 \u2014 two clicks, done. Deleting destroys data; sorting doesn\u2019t hide; manual copy is slow. Filters are the right tool.", bloom: "apply" },
    { q: "Your aunt has 40 family contacts in Excel with birthday dates. She wants \u201cwhose birthday is next?\u201d What is the quickest way?", opts: ["Filter to show people born this month, which might miss the friend whose birthday is on the 2nd of the next month", "Sort the list A to Z by name, and then read every single row to find the next birthday date by eye", "Sort the list by Birthday column, oldest to newest, and the next birthday is at the top of the sorted list", "Delete everyone whose birthday already passed this month, which loses useful info forever from the data"], ans: 2, why: "Sort by date \u2014 the closest upcoming birthday ends up on top (or near it). Filtering by month can miss the next month. Sorting by name doesn\u2019t help. Deleting destroys data forever.", bloom: "apply" },
    { q: "Your \u201cSummary\u201d sheet needs to show the total from cell B10 on a sheet called \u201cShop Sales\u201d. Which formula?", opts: ["=ShopSales!B10, which skips the space because Excel can usually figure out what the user meant anyway", "='Shop Sales'!B10, wrapping the sheet name in single quotes because the sheet name has a space in it", "=\"Shop Sales\".B10, using double quotes and a dot instead of single quotes and the exclamation mark here", "=Shop_Sales!B10, replacing the space with an underscore so Excel does not get confused by the gap"], ans: 1, why: "Sheet names with spaces need single quotes around the name, then !, then the cell. Without quotes, Excel stops at the space and errors. Dots and underscores are not Excel\u2019s way.", bloom: "apply" },
    { q: "A shared Excel file gets sorted in place by one teammate. Later, someone else opens it and their \u201crow 5 task\u201d is now in row 17. What went wrong?", opts: ["Excel has a known bug where shared files auto-reshuffle themselves every 24 hours without any user action", "Sorting in place changes row positions for EVERYONE \u2014 row numbers are not stable IDs for rows", "The file became silently corrupted during the upload and every row number shifted by exactly 12 positions", "The second teammate\u2019s laptop has a different Excel version, so rows appear in a new order on their screen"], ans: 1, why: "Sort reorders rows permanently in the saved file. Row numbers (5, 17) are positions, not IDs. If you need to reference a row, use a stable ID column (name, student ID). The bug and version excuses aren\u2019t real.", bloom: "analyze" },
    { q: "Your classmate says: \u201cJust copy-paste January\u2019s total into the Summary sheet \u2014 linking is too complex.\u201d Evaluate.", opts: ["Fully correct \u2014 copy-paste is always the best way in every single Excel situation and at every skill level", "Fully wrong \u2014 copy-paste is never allowed in Excel and the software will block any copy-paste operation today", "Not quite \u2014 copy-paste works once, but when January\u2019s number changes, the Summary stays stale and wrong", "Fully correct \u2014 copy-paste and linking both do exactly the same thing in every modern version of Excel now"], ans: 2, why: "Copy-paste gives you a static value \u2014 it won\u2019t update when January\u2019s data changes. Linking (='Jan'!B10) keeps the Summary always correct. For a one-time snapshot, paste is fine. For a live dashboard, link. Nuance wins.", bloom: "evaluate" },
    { q: "Design a monthly shop sales tracker: 12 monthly sheets and one Summary sheet that shows totals for every month.", opts: ["Copy-paste the January total into Summary once, then do the same for every next month by hand each time", "Put all 12 months on one sheet with no structure at all, and read the totals by eye whenever you need them", "Put each month on its own sheet \u00b7 on Summary, use =Jan!B50, =Feb!B50, \u2026, =Dec!B50 to pull each total live", "Make Summary identical to January\u2019s sheet and ignore the other 11 months completely for the whole year"], ans: 2, why: "One sheet per month keeps each month\u2019s data clean. The Summary sheet links to each month\u2019s total with formulas \u2014 when a monthly sheet updates, Summary updates too. Copy-paste drifts; no-structure is unsearchable; ignoring months is silly.", bloom: "create" },
  ],

  // ─── Topic 7: MS PowerPoint — Creating Presentations ───
  7: [
    { q: "Which file extension does MS PowerPoint use for a presentation?", opts: [".pptx, the standard PowerPoint format on modern Office apps", ".docx, which is actually the format used by MS Word for writing documents like essays, formal letters, and school reports", ".xlsx, which is actually the format used by MS Excel for workbooks containing numbers, formulas, and data tables in a grid", ".txt, which is the plain-text format used by the basic Notepad app for small notes with no formatting or pictures at all"], ans: 0, why: ".pptx = PowerPoint. .docx = Word. .xlsx = Excel. .txt = Notepad. Each Office app has its own format and the letters give you a hint about which app.", bloom: "remember" },
    { q: "What is the first slide in most presentations called?", opts: ["Content Slide \u2014 used for the middle slides with bullet points, pictures, and the main information on the topic", "Blank Slide \u2014 an empty slide that is used only when the other layouts simply don\u2019t fit the specific topic", "Section Header \u2014 used to divide the presentation into separate parts when there are many topics to cover", "Title Slide \u2014 the opening slide with a big title and subtitle right in the middle of the page"], ans: 3, why: "Title Slide = slide 1, the opening with the presentation title and your name. Content = most other slides. Section Header = divider. Blank = empty. Each layout has a job.", bloom: "remember" },
    { q: "Why does PowerPoint have \u201cthemes\u201d that change colours and fonts on every slide at once?", opts: ["Because each theme is actually a secret paid-only feature that only unlocks after you sign in with a premium Office account", "So the whole presentation looks consistent \u2014 pick once, every slide matches", "Because older versions of PowerPoint simply required themes \u2014 newer versions of the app ignore the theme setting completely today", "Because a theme actually changes only one slide at a time, and the user must repeat the process for every other slide one by one"], ans: 1, why: "A theme gives your deck one consistent look (same colours, same fonts, same background on every slide). Pick once, apply everywhere. Themes are free, work on every slide, and modern PowerPoint does use them fully.", bloom: "understand" },
    { q: "Why does the \u20186\u00d76\u2019 rule (about 6 lines \u00d7 6 words) matter on a slide?", opts: ["Because PowerPoint actually slows down if any single slide contains more than 36 words on it at one time", "Because most printers in most schools cannot print slides with more than 36 words on a single A4 page", "Because PowerPoint automatically deletes every word after the 36th one on any single slide of a presentation", "Audiences read slides faster than you can speak \u2014 too much text and they stop listening to you entirely"], ans: 3, why: "Your class reads ahead, finishes reading, then stops listening to you \u2014 and walks away remembering nothing. Short bullets (~6 lines of ~6 words) keep attention on the speaker. PowerPoint has no word limits and doesn\u2019t delete text.", bloom: "understand" },
    { q: "You are comparing \u201cHealthy food\u201d and \u201cJunk food\u201d on one slide, side by side with bullet lists. Which layout fits?", opts: ["Title Slide, which is designed for the first slide of a presentation and holds only a title and subtitle", "Two Content, which gives you a title at the top and two equal content boxes side by side below it", "Blank, which gives a completely empty slide and means you have to draw every line and box by hand", "Section Header, which is a divider slide between major parts of a long presentation with many topics"], ans: 1, why: "Two Content = title + two equal boxes side by side \u2014 perfect for any comparison. Title Slide is just for slide 1. Blank forces you to start from nothing. Section Header is a divider mid-deck.", bloom: "apply" },
    { q: "A Tashkent student has to talk to the class for 3 minutes about \u201cMy Summer Holidays.\u201d How many slides is a good target?", opts: ["3 to 5 slides, so each slide gets some real speaking time and the class is not reading text the whole time", "30 slides, one slide for every 6 seconds, so the class sees a new slide almost every time you change breath", "1 slide with all the information typed in a very small font to save the audience from any screen distraction", "60 slides of colourful animations so that the presentation looks more modern and very professional to the class"], ans: 0, why: "~1 minute per slide is the standard rhythm. 3 minutes = about 3\u20135 slides. 30 slides is TikTok speed, no one can follow. 1 dense slide is a wall of text. 60 is total chaos.", bloom: "apply" },
    { q: "You\u2019re presenting a school project. The class can\u2019t read the text because the font is size 14. What\u2019s the fix?", opts: ["Turn off the lights so the contrast on the projector looks stronger and the text becomes more visible", "Read every slide out loud slowly, which makes a 3-minute talk take 10 minutes and lose the audience", "Raise the font size to about 24 or more, so the back row of the class can read the slide clearly", "Ask the class to come closer and sit on the floor so they can read the tiny size 14 font from close up"], ans: 2, why: "Slides are seen from 5\u201315 metres away. Size 14 is a document size, not a slide size. Aim for 24+ for body text and 36+ for titles. Reading aloud wastes time; dimming or rearranging the class doesn\u2019t solve the text-size problem.", bloom: "apply" },
    { q: "Your friend\u2019s 20-slide presentation has 5 different colour themes, 3 different font families, and blinking backgrounds. Why is this bad?", opts: ["Because PowerPoint automatically charges extra money for using more than one theme in a single presentation file", "Because the laptop running the presentation slows down with more than two themes, leading to obvious freezing", "Because the visual chaos pulls the audience\u2019s focus away from the message \u2014 they notice style, not content", "Because having more than one theme always causes the PowerPoint file to become silently corrupted in saving"], ans: 2, why: "Too much variety creates noise \u2014 the audience notices the flashing and the mismatched fonts instead of the message. One theme, two fonts max, no blinking. The other reasons (fees, corruption, slowdowns) aren\u2019t real.", bloom: "analyze" },
    { q: "A classmate says: \u201cMy slides are full of text so I don\u2019t have to remember anything \u2014 I can just read them.\u201d Evaluate.", opts: ["Fully correct \u2014 reading your slides word for word is the best possible way to make sure you never miss a single point or idea", "Fully wrong \u2014 every student should memorise every single word of every slide before stepping up in front of the class on the big day", "Not quite \u2014 reading slides makes the class tune out; slides show key points, you say the rest", "Fully correct \u2014 nobody in any job anywhere actually looks at the speaker during any presentation with slides in any real office today"], ans: 2, why: "If slides are full text and you read them, the class reads faster than you speak, and they stop listening. Slides should have KEY POINTS. Your speaking adds the detail. Use Presenter View to see your notes privately.", bloom: "evaluate" },
    { q: "Design a 5-slide plan for a 4-minute talk \u201cMy Favourite Place in Tashkent.\u201d", opts: ["Slide 1 only \u2014 a single full-text essay of 400 words typed at size 10 right in the middle of one slide with no pictures", "(1) Title \u00b7 (2) Why I love it \u00b7 (3) Photo + description \u00b7 (4) Fun fact \u00b7 (5) Thanks", "30 slides with only one single word on each, flashed for 8 seconds each, with no pictures or actual information given at all", "One whole slide for every single sentence of your speech, which means around 60 slides for a 4-minute talk, each with tiny words"], ans: 1, why: "About 1 minute per slide, each with ONE clear idea and a visual. Title \u2192 reason \u2192 photo \u2192 fun fact \u2192 close. Essay-on-one-slide kills attention; 30 slides in 4 min is TikTok; 60 slides is impossible to pace.", bloom: "create" },
  ],

  // ─── Topic 8: MS PowerPoint — Master Slides & Slide Shows ───
  8: [
    { q: "What does the Slide Master in PowerPoint control?", opts: ["Only the very first slide of the presentation, which then shows as the cover of the whole deck to the audience", "The speaker-notes font and size, but nothing else on the slides that the actual audience will see in the room", "The look (logo, background, fonts) of ALL slides \u2014 edit it once and every slide in the deck updates", "The time that each slide stays on the screen during the auto-play mode, but not what the slide looks like"], ans: 2, why: "Slide Master = the \u201cstamp\u201d for every slide. Edit once there (logo, background, heading font) and all slides update. Timings and speaker notes are separate features.", bloom: "remember" },
    { q: "Which keyboard shortcut starts a PowerPoint slide show from the very first slide?", opts: ["F5 \u2014 the standard shortcut on Windows laptops that starts the whole presentation from slide number 1 at once", "Shift+F5 \u2014 which instead starts the slide show from the slide you currently have selected on the screen", "Ctrl+F5 \u2014 which is not a real PowerPoint shortcut and does nothing special when pressed inside the application", "Alt+F5 \u2014 which opens the Presenter View setup but does not actually start the slide show from the first slide"], ans: 0, why: "F5 = start from the beginning. Shift+F5 = start from the current slide (good for practicing one section). Ctrl+F5 and Alt+F5 are not standard start shortcuts.", bloom: "remember" },
    { q: "Why are \u201ctransitions\u201d and \u201canimations\u201d treated as two separate things in PowerPoint?", opts: ["Transitions are the effect BETWEEN slides; animations are the effect of OBJECTS inside ONE slide", "Because they are actually the same thing \u2014 Microsoft just gave the single feature two different names by mistake", "Because transitions only work with Wi-Fi and animations only work when the laptop is in airplane mode", "Because transitions cost money to use and animations are the cheaper free version that most people use"], ans: 0, why: "Transition = effect when moving from slide A to slide B (fade, wipe). Animation = effect on a thing ON one slide (title flies in, bullets appear). Two tabs, two purposes. They are not the same feature.", bloom: "understand" },
    { q: "Why are too many animations on a slide considered a bad practice?", opts: ["Because PowerPoint will automatically charge the user extra money for each animation beyond the first free three", "Because the computer physically overheats when more than four animations run on any one slide at one time", "Because too much motion distracts the audience from what you are actually saying \u2014 people notice the motion", "Because animations actually only work on Windows laptops and not on Mac laptops, so always skip them entirely"], ans: 2, why: "If objects spin, bounce, and zoom, your class watches the motion and stops listening. Animations should REVEAL a point (one bullet per click), not decorate. No fees, no overheating, no Mac ban.", bloom: "understand" },
    { q: "You have finished editing your 10 slides and want to practice from slide 5 (without starting from slide 1 every time). Which shortcut?", opts: ["F5 \u2014 this actually starts the show from slide 1, so you\u2019d waste time pressing Next four times every practice", "Shift+F5 \u2014 starts the slide show from the slide you are currently on, perfect for practicing one section", "Ctrl+N \u2014 this actually opens a brand new PowerPoint file, which is definitely not what the user wants here", "Ctrl+F5 \u2014 which is not a real PowerPoint shortcut and does nothing useful inside the running application"], ans: 1, why: "Shift+F5 = start from CURRENT slide. Saves time when practicing. F5 = from slide 1 (wrong tool here). Ctrl+N opens a new file. Ctrl+F5 is not a standard shortcut.", bloom: "apply" },
    { q: "Your teacher asks you to put the school logo on every slide of a 25-slide presentation. What\u2019s the fastest way?", opts: ["Copy the logo and paste it into the top-right corner of every single slide, one by one, across 25 clicks", "Email the logo to every student in the class and ask them to paste it onto their own copy of the slides", "Take a screenshot of the logo and make it your desktop wallpaper so it shows on each slide automatically", "Open View \u2192 Slide Master, paste the logo ONCE onto the master slide, and every slide gets the logo"], ans: 3, why: "Slide Master = edit once, applies everywhere. Pasting 25 times is slow and easy to misalign. Wallpaper doesn\u2019t show on slides. Emailing classmates is not an answer to a slide-building question.", bloom: "apply" },
    { q: "You want your class to see bullet points appear ONE AT A TIME as you click (so they can\u2019t read ahead). Which feature?", opts: ["A Transition set to Fade between bullets, which actually moves between slides and not between bullets on a slide", "An Animation on the bullet list with \u201cBy Paragraph\u201d \u2014 one bullet appears each time you click the mouse", "The Slide Master, which controls the global look of slides but does not control per-click reveal timing at all", "One whole separate slide for each bullet, which means 5 bullets become 5 separate slides in the presentation"], ans: 1, why: "Animation on a bullet list with \u201cBy Paragraph\u201d reveals one bullet per click. Transitions are between slides. Slide Master is for global look. One-slide-per-bullet is possible but wastes slides and effort.", bloom: "apply" },
    { q: "Your friend\u2019s presentation looked fine on his laptop but all the fonts changed on the school\u2019s computer. What caused it?", opts: ["The school\u2019s laptop is completely broken and needs to be fully replaced before the next school presentation day", "The font your friend used is missing from the school\u2019s laptop \u2014 embed fonts or use common ones like Arial", "PowerPoint always randomly changes fonts when you open a file on a different computer \u2014 it is a classic bug", "The file was silently corrupted on the USB stick during transfer, which changed every font in the presentation"], ans: 1, why: "Fonts live on the computer\u2019s OS, not inside the file by default. When the file opens on a PC that doesn\u2019t have that font, PowerPoint swaps in a default font. Fix: embed fonts (File \u2192 Options \u2192 Save) or use safe fonts like Arial or Calibri.", bloom: "analyze" },
    { q: "Your cousin says: \u201cEvery slide should have 5 different animations so the audience stays interested.\u201d Evaluate.", opts: ["Fully right \u2014 the more motion on every slide, the more engaging the whole presentation is for every audience", "Fully right \u2014 modern audiences only pay attention when there are at least 10 animations on every single slide", "Fully wrong \u2014 no slide should ever have any animation, because all animations always distract from the message", "Not quite \u2014 a few animations can help reveal points; too many become noise and hide your actual message"], ans: 3, why: "Animations that reveal one bullet at a time help the audience. 5+ random animations per slide look amateur and steal attention from you. The right answer is \u201cuse them with purpose.\u201d All-or-nothing views both fail.", bloom: "evaluate" },
    { q: "Design a Slide Master setup for your school\u2019s official 15-slide presentation template that any teacher can use.", opts: ["Logo top-right \u00b7 school name bottom-left \u00b7 page number \u00b7 one heading + one body font", "Master slide with no logo, no colours, and no fonts set \u2014 let every teacher design their own look from scratch each single term", "Paste the school logo 15 times onto 15 individual slides and copy the same file to every single teacher\u2019s laptop every school term", "Hide the Slide Master feature from every teacher, so that each of them has to build every single slide one at a time every term again"], ans: 0, why: "Master holds the global school branding (logo, name, page number, two fonts). Teachers only fill in content. New slides auto-inherit the look. \u201cLet teachers decide\u201d loses consistency; pasting 15 times defeats the master\u2019s purpose.", bloom: "create" },
  ],

  // ─── Topic 9: Which Tool When? ───
  9: [
    { q: "What is the \u201cgolden rule\u201d for picking MS Word, Excel, or PowerPoint?", opts: ["Word = writing, Excel = numbers, PowerPoint = presenting \u2014 match the main job of the task to the tool", "Always use MS Word, because it is the oldest of the three and most teachers are comfortable with it in class", "Always use MS Excel, because it has the most features and the most flexibility out of all three Office apps", "Always use PowerPoint, because visual slides always work best for every possible classroom assignment ever"], ans: 0, why: "Match the main job: writing \u2192 Word, numbers \u2192 Excel, presenting \u2192 PowerPoint. \u201cAlways one tool\u201d ignores the differences. Each tool was built for a different purpose.", bloom: "remember" },
    { q: "Which tool is best for writing a formal letter to your school director?", opts: ["MS Excel, because each single sentence can go into its own cell and give the final letter a tidy and structured grid layout", "MS Word \u2014 it handles headings, paragraphs, signatures, and a print-ready layout", "MS PowerPoint, because a formal letter is really just one long slide that can easily be saved as a document at the very end of the talk", "Notepad, because a simple .txt file is always easier to read than any kind of document made by any of the modern word processors today"], ans: 1, why: "A formal letter needs paragraphs, date, address, signature, and a nice print. That\u2019s Word\u2019s home ground. Excel is a grid. PowerPoint is for slides. Notepad has no formatting.", bloom: "remember" },
    { q: "Why would you NOT write a 5-page school essay in MS Excel, even though Excel cells can hold text?", opts: ["Because MS Excel has a hard rule that every single cell can only store 10 words of text before it cuts off", "Because Excel actually does not support text at all \u2014 only numbers can be placed into its grid structure", "Because Excel files are always too big to email to your teacher \u2014 they cannot be attached to any message", "Because Excel is a grid \u2014 essays need flowing paragraphs, headings, and page breaks, which Word handles"], ans: 3, why: "Excel is a grid for rows and columns. Essays are prose \u2014 they need paragraph flow, headings, page numbers, pagination. Excel gives none of that. Excel DOES hold text, and files email fine, but it\u2019s the wrong tool for prose.", bloom: "understand" },
    { q: "Why is Excel the natural choice for tracking a family budget in UZS?", opts: ["Because Excel is the only Microsoft app that can open on any laptop model \u2014 the others require paid versions", "Because Excel has formulas that add and average numbers, and sort/filter for months \u2014 built for number work", "Because MS Word cannot store any numbers at all \u2014 it is a text-only app and would reject every UZS value", "Because MS PowerPoint is designed for budgets and it prints a family\u2019s monthly totals directly on a colour A4 page"], ans: 1, why: "A budget is rows of numbers with totals and averages \u2014 the exact thing Excel was built for. Word and PowerPoint can store numbers, but neither adds them automatically. Match the job to the tool.", bloom: "understand" },
    { q: "Your cousin has to track the attendance of 50 students for the whole semester. Which tool?", opts: ["MS Word with a huge table, because you can make borders look very neat and the tab key moves across cells", "MS PowerPoint with text boxes, because slides are a modern way to track attendance over a long time period", "Notepad with one name per line, because a .txt file is simpler than any other option for tracking 50 students", "MS Excel, because tabular data \u2014 rows of names, columns of dates \u2014 plus totals is exactly what Excel is for"], ans: 3, why: "50 students \u00d7 many dates + totals = spreadsheet. Excel sorts, filters, counts, and totals in seconds. Word tables can\u2019t sum. PowerPoint is slides. Notepad has no columns.", bloom: "apply" },
    { q: "You are preparing a 5-minute class presentation about your favourite book. Which tool?", opts: ["MS Word, which is fine for writing a book report but not great for speaking with slides in front of a class", "MS Excel, because you can list the chapters in column A and the number of pages for each in column B nicely", "MS PowerPoint, because you need slides with a book cover image and short bullet points for the class to see", "Notepad, because plain text is the simplest way to speak in front of the class without wasting too much time"], ans: 2, why: "Standing up + slides on the screen = PowerPoint. Word is for the written report. Excel is for chapter counts but not the visual talk. Notepad has no slides at all.", bloom: "apply" },
    { q: "You need to make a CV (resume) to apply for a part-time Tashkent shop assistant job. Which tool?", opts: ["MS Word \u2014 a CV is a formatted one-page document with name, education, and work history", "MS PowerPoint, because your CV can be one big visual slide with many colourful shapes and many fancy animations on it for the shop owner", "MS Excel, because you can write every job and every qualification inside a separate cell for a very neat row-by-row final layout", "Notepad, because sending your CV as a plain .txt file is always the simplest way to apply for any part-time job in the city of Tashkent"], ans: 0, why: "A CV is a formatted one-page document \u2014 headings, bullet lists, your name bold at the top. Word or Google Docs handle this. PowerPoint is for slides. Excel is a grid. Notepad has no formatting.", bloom: "apply" },
    { q: "A small bakery uses MS Word to track daily sales \u2014 one paragraph per day. After 3 months, what\u2019s the main problem?", opts: ["The Word file will become corrupted and they will lose every single day of sales data they entered for months", "There\u2019s no easy way to total monthly sales \u2014 prose can\u2019t be summed, sorted, or filtered like Excel rows can", "The bakery will be fined by the tax office for using MS Word \u2014 it\u2019s illegal for any business to use Word at all", "Nothing is wrong at all \u2014 Word is perfect for tracking business sales data over any length of time, as long as needed"], ans: 1, why: "Sales data is numbers. Word hides them inside prose \u2014 impossible to SUM, AVERAGE, SORT, FILTER. After 3 months, the bakery can\u2019t answer \u201cwhat did we sell last Tuesday?\u201d quickly. Use Excel. Files don\u2019t corrupt; no tax law forbids Word.", bloom: "analyze" },
    { q: "A teacher proposes: \u201cDo everything in Google Docs \u2014 documents, spreadsheets, slides.\u201d Evaluate.", opts: ["Fully correct \u2014 one app is always simpler, and Google Docs alone can do every office task at any school level", "Fully wrong \u2014 Google has no tools at all that can replace Microsoft Office in any situation, not even basic tasks", "Not quite \u2014 Docs, Sheets, and Slides cover most school tasks, but for complex spreadsheets Excel is still stronger", "Fully correct \u2014 Google Docs is always better than Microsoft Office for every school task, no matter the size or type"], ans: 2, why: "Google Docs, Sheets, Slides cover the three categories and are free and collaborative \u2014 great for school. But Sheets is weaker on big or complex data (power formulas, pivot tables). A balanced \u201cmostly fine, some limits\u201d is the honest view.", bloom: "evaluate" },
    { q: "Design a workflow for a class group project: tracking 20 menu prices for a Tashkent caf\u00e9, writing a 2-page report, and presenting to the class.", opts: ["Do everything in one MS Word file \u2014 it will hold prices, report, and slides all in one long document together", "Put all three pieces into MS PowerPoint \u2014 one slide for prices, one for the report, and one for the talk", "Excel for the price table (with totals and sorting), Word for the 2-page report, PowerPoint for the class talk", "Skip the project entirely and just give a verbal summary to the teacher without using any Office software at all"], ans: 2, why: "Each piece fits one tool: prices = Excel (rows, totals, sort), report = Word (formatted prose), class talk = PowerPoint (slides). You can paste the Excel price table into both. Using one tool for everything forces each part to fight the software.", bloom: "create" },
  ],
};
